// applyEmphasis converts the first __pair__ to <strong> and the first _pair_ to <em>.
func applyEmphasis(markdown string) string {
	markdown = replaceFirstPair(markdown, "__", "<strong>", "</strong>")
	markdown = replaceFirstPair(markdown, "_", "<em>", "</em>")
	return markdown
}

func replaceFirstPair(s, delim, open, close string) string {
	start := strings.Index(s, delim)
	if start < 0 {
		return s
	}
	end := strings.Index(s[start+len(delim):], delim)
	if end < 0 {
		return s
	}
	end += start + len(delim)
	return s[:start] + open + s[start+len(delim):end] + close + s[end+len(delim):]
}
```

